function(container, apiUrl, tables) {
    // 業務ロジックモジュールをインポート
    const { 
        collectSalesData, 
        classifySalesDataByProduct, 
        classifySalesDataByStore, 
        filterValidProductData, 
        collectWeatherData, 
        collectEventData, 
        collectSeasonalData, 
        analyzeCorrelationSalesWeather, 
        analyzeCorrelationSalesEvent, 
        analyzeCorrelationSalesSeason, 
        compareWithHistoricalData, 
        findAlternativeComparisonData, 
        validateComparisonPeriod 
    } = window.aivicLogic || {};

    // DOM要素を取得
    const analysisTypeSelect = container.querySelector('#analysisType');
    const startDateInput = container.querySelector('#startDate');
    const endDateInput = container.querySelector('#endDate');
    const productSelect = container.querySelector('#productSelect');
    const storeSelect = container.querySelector('#storeSelect');
    const executeAnalysisBtn = container.querySelector('#executeAnalysis');
    const compareBtn = container.querySelector('#compareAnalysis');
    const correlationResultDiv = container.querySelector('#correlationResult');
    const comparisonResultDiv = container.querySelector('#comparisonResult');
    const correlationChart = container.querySelector('#correlationChart');
    const comparisonChart = container.querySelector('#comparisonChart');

    // 分析結果を保存する変数
    let currentAnalysisResult = null;

    // 初期データ読み込み
    loadInitialData();

    async function loadInitialData() {
        try {
            // 商品データ読み込み
            const products = await window.aivicApi.list('products');
            populateSelect(productSelect, products, 'id', 'name');

            // 店舗データ読み込み
            const stores = await window.aivicApi.list('stores');
            populateSelect(storeSelect, stores, 'id', 'name');

        } catch (error) {
            window.aivicNotify.error('初期データの読み込みに失敗しました: ' + error.message);
        }
    }

    function populateSelect(selectElement, data, valueField, textField) {
        selectElement.innerHTML = '<option value="">選択してください</option>';
        data.forEach(item => {
            const option = document.createElement('option');
            option.value = item[valueField];
            option.textContent = item[textField];
            selectElement.appendChild(option);
        });
    }

    // 相関分析実行
    executeAnalysisBtn.addEventListener('click', async () => {
        try {
            const analysisType = analysisTypeSelect.value;
            const startDate = startDateInput.value;
            const endDate = endDateInput.value;
            const productId = productSelect.value;
            const storeId = storeSelect.value;

            if (!analysisType || !startDate || !endDate) {
                window.aivicNotify.error('分析種別、開始日、終了日を入力してください');
                return;
            }

            // 売上データ収集
            const salesData = await collectSalesData(startDate, endDate, productId, storeId);

            if (!salesData || salesData.length === 0) {
                window.aivicNotify.error('指定期間の売上データが見つかりません');
                return;
            }

            let analysisResult = null;

            // 分析種別に応じて相関分析を実行
            switch (analysisType) {
                case 'weather':
                    const weatherData = await collectWeatherData(startDate, endDate);
                    analysisResult = analyzeCorrelationSalesWeather(salesData, weatherData);
                    break;
                case 'event':
                    const eventData = await collectEventData(startDate, endDate);
                    analysisResult = analyzeCorrelationSalesEvent(salesData, eventData);
                    break;
                case 'season':
                    const seasonalData = await collectSeasonalData(startDate, endDate);
                    analysisResult = analyzeCorrelationSalesSeason(salesData, seasonalData);
                    break;
                default:
                    window.aivicNotify.error('不正な分析種別です');
                    return;
            }

            // 結果を保存
            currentAnalysisResult = analysisResult;

            // 結果を表示
            displayCorrelationResult(analysisResult);
            drawCorrelationChart(analysisResult);

            window.aivicNotify.success('相関分析が完了しました');

        } catch (error) {
            window.aivicNotify.error('相関分析に失敗しました: ' + error.message);
        }
    });

    // 比較分析実行
    compareBtn.addEventListener('click', async () => {
        try {
            if (!currentAnalysisResult) {
                window.aivicNotify.error('先に相関分析を実行してください');
                return;
            }

            const startDate = startDateInput.value;
            const endDate = endDateInput.value;

            // 比較期間の妥当性チェック
            const validationResult = validateComparisonPeriod(startDate, endDate);
            if (!validationResult.isValid) {
                window.aivicNotify.error(validationResult.message);
                return;
            }

            // 過去データとの比較
            let comparisonResult = await compareWithHistoricalData(currentAnalysisResult, startDate, endDate);

            // 代替比較データの検索
            if (!comparisonResult || comparisonResult.confidence < 0.5) {
                const alternativeData = await findAlternativeComparisonData(currentAnalysisResult);
                if (alternativeData) {
                    comparisonResult = alternativeData;
                }
            }

            if (!comparisonResult) {
                window.aivicNotify.error('比較可能なデータが見つかりません');
                return;
            }

            // 比較結果を表示
            displayComparisonResult(comparisonResult);
            drawComparisonChart(comparisonResult);

            window.aivicNotify.success('比較分析が完了しました');

        } catch (error) {
            window.aivicNotify.error('比較分析に失敗しました: ' + error.message);
        }
    });

    function displayCorrelationResult(result) {
        if (!result) return;

        correlationResultDiv.innerHTML = `
            <div class="analysis-result">
                <h4>相関分析結果</h4>
                <div class="result-item">
                    <label>相関係数:</label>
                    <span class="correlation-value ${getCorrelationClass(result.correlation)}">${result.correlation.toFixed(3)}</span>
                </div>
                <div class="result-item">
                    <label>信頼度:</label>
                    <span>${(result.confidence * 100).toFixed(1)}%</span>
                </div>
                <div class="result-item">
                    <label>サンプル数:</label>
                    <span>${result.sampleCount}</span>
                </div>
                <div class="result-item">
                    <label>分析結果:</label>
                    <span>${result.interpretation}</span>
                </div>
            </div>
        `;
    }

    function displayComparisonResult(result) {
        if (!result) return;

        comparisonResultDiv.innerHTML = `
            <div class="comparison-result">
                <h4>比較分析結果</h4>
                <div class="result-item">
                    <label>比較期間:</label>
                    <span>${result.comparisonPeriod}</span>
                </div>
                <div class="result-item">
                    <label>相関係数の変化:</label>
                    <span class="${getChangeClass(result.correlationChange)}">${result.correlationChange > 0 ? '+' : ''}${result.correlationChange.toFixed(3)}</span>
                </div>
                <div class="result-item">
                    <label>統計的有意性:</label>
                    <span>${result.significance ? '有意' : '非有意'}</span>
                </div>
                <div class="result-item">
                    <label>比較結果:</label>
                    <span>${result.summary}</span>
                </div>
            </div>
        `;
    }

    function drawCorrelationChart(result) {
        if (!result || !result.chartData) return;

        correlationChart.innerHTML = '';

        // 簡易チャート描画
        const canvas = document.createElement('canvas');
        canvas.width = 400;
        canvas.height = 300;
        correlationChart.appendChild(canvas);

        const ctx = canvas.getContext('2d');

        // 散布図を描画
        const data = result.chartData;
        const maxX = Math.max(...data.map(d => d.x));
        const maxY = Math.max(...data.map(d => d.y));

        data.forEach(point => {
            const x = (point.x / maxX) * 350 + 25;
            const y = 275 - (point.y / maxY) * 250;

            ctx.beginPath();
            ctx.arc(x, y, 3, 0, 2 * Math.PI);
            ctx.fillStyle = '#007bff';
            ctx.fill();
        });

        // 回帰直線を描画
        if (result.regressionLine) {
            ctx.beginPath();
            ctx.moveTo(25, 275 - (result.regressionLine.start / maxY) * 250);
            ctx.lineTo(375, 275 - (result.regressionLine.end / maxY) * 250);
            ctx.strokeStyle = '#dc3545';
            ctx.lineWidth = 2;
            ctx.stroke();
        }
    }

    function drawComparisonChart(result) {
        if (!result || !result.chartData) return;

        comparisonChart.innerHTML = '';

        // 比較チャート描画
        const canvas = document.createElement('canvas');
        canvas.width = 400;
        canvas.height = 300;
        comparisonChart.appendChild(canvas);

        const ctx = canvas.getContext('2d');

        // 棒グラフで比較結果を表示
        const currentValue = result.currentCorrelation;
        const historicalValue = result.historicalCorrelation;

        const barWidth = 80;
        const maxValue = Math.max(Math.abs(currentValue), Math.abs(historicalValue));

        // 現在の値
        const currentHeight = (Math.abs(currentValue) / maxValue) * 200;
        ctx.fillStyle = '#007bff';
        ctx.fillRect(100, 250 - currentHeight, barWidth, currentHeight);

        // 過去の値
        const historicalHeight = (Math.abs(historicalValue) / maxValue) * 200;
        ctx.fillStyle = '#6c757d';
        ctx.fillRect(220, 250 - historicalHeight, barWidth, historicalHeight);

        // ラベル
        ctx.fillStyle = '#000';
        ctx.font = '12px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('現在', 140, 270);
        ctx.fillText('過去', 260, 270);
    }

    function getCorrelationClass(correlation) {
        const abs = Math.abs(correlation);
        if (abs >= 0.7) return 'strong-correlation';
        if (abs >= 0.3) return 'moderate-correlation';
        return 'weak-correlation';
    }

    function getChangeClass(change) {
        if (change > 0.1) return 'positive-change';
        if (change < -0.1) return 'negative-change';
        return 'neutral-change';
    }
}
